command:
C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -NoProfile -Command "& {
$nodes = (Invoke-RestMethod -Uri 'http://127.0.0.1:3080/v3/projects/CampusNetwork_02/nodes').value
foreach ($node in $nodes) {
  $name = $node.node_id
  $u1 = 'http://127.0.0.1:3080/v3/projects/CampusNetwork_02/nodes/' + $name + '/command?cmd=display%20current-configuration'
  $u0 = 'http://127.0.0.1:3080/v3/projects/CampusNetwork-for-perf_02/nodes/' + $name + '/command?cmd=display%20current-configuration'
  $a = (Invoke-RestMethod -Uri $u1).output
  $b = (Invoke-RestMethod -Uri $u0).output
  if (($a -notlike 'Error:*') -and ($b -notlike 'Error:*')) {
    $al = $a -split [char]10 | ForEach-Object { $_.TrimEnd([char]13) } | Where-Object { $_ -notmatch 'Last configuration' }
    $bl = $b -split [char]10 | ForEach-Object { $_.TrimEnd([char]13) } | Where-Object { $_ -notmatch 'Last configuration' }
    $d = Compare-Object -ReferenceObject $bl -DifferenceObject $al
    if ($d) {
      Write-Output ('=== ' + $name + ' ===')
      $d | ForEach-Object { Write-Output ($_.SideIndicator + ' ' + $_.InputObject) }
    }
  }
}
}"
